"""Finite state machine model for bounded model checking (BMC).

Models a simple mutual-exclusion protocol: two processes each move
through IDLE -> WAIT -> CRITICAL, guarded by a lock that is either free
or held by one of the processes. Exactly one process moves at a time
(interleaving semantics).

Safety property: the two processes must never be in the critical
section at the same time, expressed as a set of bad states.
"""

IDLE = "idle"
WAIT = "wait"
CRIT = "crit"

FREE = "free"
HELD1 = "held1"
HELD2 = "held2"

# A state is (process-1 state, process-2 state, lock state).
STATES = frozenset(
    (s1, s2, lock)
    for s1 in (IDLE, WAIT, CRIT)
    for s2 in (IDLE, WAIT, CRIT)
    for lock in (FREE, HELD1, HELD2)
)

INITIAL_STATES = frozenset({(IDLE, IDLE, FREE)})


def _steps(state, process):
    """Successors of `state` when only `process` (1 or 2) takes a step."""
    s1, s2, lock = state
    if process == 1:
        mine, other, held = s1, s2, HELD1
    else:
        mine, other, held = s2, s1, HELD2

    if mine == IDLE:
        mine_next = WAIT
    elif mine == WAIT:
        if lock != FREE:
            return frozenset()  # lock busy, cannot acquire
        mine_next = CRIT
    else:
        mine_next = IDLE  # release

    if mine_next == CRIT:
        lock_next = held
    elif mine == CRIT:
        lock_next = FREE
    else:
        lock_next = lock

    if process == 1:
        return frozenset({(mine_next, other, lock_next)})
    return frozenset({(other, mine_next, lock_next)})


def _successor_map():
    result = {}
    for state in STATES:
        result[state] = _steps(state, 1) | _steps(state, 2)
    return result


SUCCESSORS = _successor_map()


def successors(state):
    """Next-state relation: all states reachable from `state` in one step."""
    return SUCCESSORS[state]


# The next-state relation as a set of (source, target) edges.
TRANSITIONS = frozenset(
    (src, dst) for src, dsts in SUCCESSORS.items() for dst in dsts
)

# Safety property: mutual exclusion is violated whenever both processes
# are in the critical section, regardless of the lock value.
BAD_STATES = frozenset(s for s in STATES if s[0] == CRIT and s[1] == CRIT)


if __name__ == "__main__":
    reachable = set(INITIAL_STATES)
    frontier = set(INITIAL_STATES)
    while frontier:
        frontier = {d for s in frontier for d in successors(s)} - reachable
        reachable |= frontier

    print(f"states:               {len(STATES)}")
    print(f"initial states:       {len(INITIAL_STATES)}")
    print(f"transitions:          {len(TRANSITIONS)}")
    print(f"bad states:           {len(BAD_STATES)}")
    print(f"reachable states:     {len(reachable)}")
    print(f"bad states reachable: {len(reachable & BAD_STATES)}")
